import{c as t,Q as n,j as r,m as a}from"./chunks/framework.BwfbE4MI.js";const p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1779859199000}'),i={name:"getting-started.md"};function o(l,e,s,d,h,c){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><h2 id="_1-get-an-n8n-instance" tabindex="-1">1. Get an n8n instance <a class="header-anchor" href="#_1-get-an-n8n-instance" aria-label="Permalink to &quot;1. Get an n8n instance&quot;">​</a></h2><p><strong>n8n Cloud</strong> is the easiest: <a href="https://n8n.partnerlinks.io/n8n-nodes-sharetribe" target="_blank" rel="noreferrer">start a free trial</a>.</p><p>Want to self-host? <a href="https://render.com" target="_blank" rel="noreferrer">Render</a> is a common pick - <a href="https://render.com/docs/deploy-n8n" target="_blank" rel="noreferrer">Render&#39;s n8n deploy doc</a>. Other options in <a href="https://docs.n8n.io/hosting/installation/server-setups/" target="_blank" rel="noreferrer">n8n&#39;s hosting guides</a>.</p><h2 id="_2-install-the-sharetribe-node" tabindex="-1">2. Install the Sharetribe node <a class="header-anchor" href="#_2-install-the-sharetribe-node" aria-label="Permalink to &quot;2. Install the Sharetribe node&quot;">​</a></h2><p>Verified community nodes install straight from n8n&#39;s node picker.</p><ol><li>In n8n, open the editor and click <strong>+</strong> to open the <strong>Nodes panel</strong>.</li><li>Search <strong>Sharetribe</strong>.</li><li>Pick the result with the verified badge.</li><li>Click <strong>Install node</strong>.</li></ol><h2 id="_3-get-integration-api-credentials" tabindex="-1">3. Get Integration API credentials <a class="header-anchor" href="#_3-get-integration-api-credentials" aria-label="Permalink to &quot;3. Get Integration API credentials&quot;">​</a></h2><p>Available on <strong>Build</strong>, <strong>Pro</strong>, and <strong>Extend</strong> (including the free trial).</p><ol><li>Open <a href="https://console.sharetribe.com/advanced/applications" target="_blank" rel="noreferrer">Sharetribe Console → Build → Advanced → Applications</a>.</li><li>Add a new application of type <strong>Integration API</strong>.</li><li>Copy the <strong>Client ID</strong> and <strong>Client secret</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Keep the secret inside n8n&#39;s credentials settings. Don&#39;t paste it anywhere else.</p></div><h2 id="_4-add-the-credential-in-n8n" tabindex="-1">4. Add the credential in n8n <a class="header-anchor" href="#_4-add-the-credential-in-n8n" aria-label="Permalink to &quot;4. Add the credential in n8n&quot;">​</a></h2><p>In n8n: <strong>Credentials → New → Sharetribe Integration API</strong>.</p><p><strong>Extend plan (also Build, Trial):</strong></p><ul><li>Paste your Integration API Client ID and Client Secret.</li><li><strong>Sharetribe Plan:</strong> Extend.</li><li><strong>Marketplace API Client ID:</strong> create a second application of type <strong>Marketplace API</strong> in Console and paste its Client ID here.</li></ul><p><strong>Pro plan:</strong></p><ul><li>Paste your Integration API Client ID and Client Secret.</li><li><strong>Sharetribe Plan:</strong> Pro.</li><li><strong>Marketplace URL:</strong> your marketplace URL (e.g. <code>https://example.com</code>).</li></ul><h2 id="_5-build-your-first-workflow" tabindex="-1">5. Build your first workflow <a class="header-anchor" href="#_5-build-your-first-workflow" aria-label="Permalink to &quot;5. Build your first workflow&quot;">​</a></h2><p>New to n8n? See <a href="https://docs.n8n.io/try-it-out/" target="_blank" rel="noreferrer">n8n&#39;s Try it out guide</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/n8n-nodes-sharetribe-docs/templates">Workflow templates</a> - copy and paste a ready-made workflow.</li><li><a href="/n8n-nodes-sharetribe-docs/faq">FAQ</a> - what n8n is, what this node does, plans, support.</li></ul>',21)])])}const u=t(i,[["render",o]]);export{p as __pageData,u as default};
